import raw from './gallery.json'

/**
 * The gallery manifest is generated by `npm run import-photos`
 * (see scripts/import-photos.mjs) and committed to the repo so the site can be
 * built and deployed without access to the original photos folder.
 */
export interface Photo {
  slug: string
  /** Full-size optimised WebP — used by the lightbox. */
  src: string
  /** Smaller WebP — used by the gallery grid. */
  thumb: string
  width: number
  height: number
  /** Tiny inline WebP used as a blur-up placeholder. */
  blur: string
  alt: string
}

export interface HeroImage {
  slug: string
  src1280: string
  src1920: string
  /** 1200×630 JPEG also referenced by the Open Graph tags in index.html. */
  poster: string
  /** Intrinsic width of the widest hero image (for width/height attributes). */
  width: number
  height: number
  alt: string
}

export interface GalleryManifest {
  generatedAt: string
  hero: HeroImage
  photos: Photo[]
}

const gallery = raw as GalleryManifest

/**
 * Vite exposes the deploy base path here ('/' in dev, '/dorpon-website/' on
 * GitHub Pages). Prefixing the generated `/photos/...` paths keeps every image
 * working no matter which sub-path the site is hosted under.
 */
const BASE = import.meta.env.BASE_URL

function asset(path: string): string {
  if (/^(?:https?:|data:)/.test(path)) return path
  return `${BASE}${path.replace(/^\/+/, '')}`
}

export const hero: HeroImage = {
  ...gallery.hero,
  src1280: asset(gallery.hero.src1280),
  src1920: asset(gallery.hero.src1920),
  poster: asset(gallery.hero.poster),
}

export const photos: Photo[] = gallery.photos.map((photo) => ({
  ...photo,
  src: asset(photo.src),
  thumb: asset(photo.thumb),
}))
